using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.Execution;using ProMaxx2.QA.Application.Projects;using ProMaxx2.QA.Application.TestManagement;using ProMaxx2.QA.Api.Services;using ProMaxx2.QA.Infrastructure.Persistence;
namespace ProMaxx2.QA.Api.Controllers;
public sealed record GenerateTestCycleAiRequest(Guid ProjectId,Guid ReleaseId,Guid BuildId,Guid EnvironmentId,Guid?TestSuiteId);
[ApiController,Route("api/v1"),Authorize(Policy="ExecutionRun"),RequireProjectAccess]
public sealed class TestCyclesController(TestCycleService service,TestCycleAiService ai,ProjectService projects,TestSuiteService suites,QaDbContext db):ControllerBase
{
 [HttpGet("test-environments")]public Task<IReadOnlyList<EnvironmentDto>>Environments([FromQuery]Guid?projectId,CancellationToken ct)=>service.EnvironmentsAsync(projectId,ct);[HttpPost("test-environments")]public async Task<ActionResult<EnvironmentDto>>CreateEnvironment(SaveEnvironmentRequest r,CancellationToken ct)=>Ok(await service.CreateEnvironmentAsync(r,ct));
 [HttpGet("test-cycles")]public Task<TestCycleListResultDto>List([FromQuery]Guid?projectId,[FromQuery]string?search,[FromQuery]string?status,[FromQuery]int page=1,[FromQuery]int size=20,CancellationToken ct=default)=>service.ListAsync(projectId,search,status,page,size,ct);[HttpGet("test-cycles/options")]public Task<IReadOnlyList<TestCycleOptionDto>>Options([FromQuery]Guid?projectId,CancellationToken ct=default)=>service.ListOptionsAsync(projectId,ct);[HttpPost("test-cycles")]public async Task<ActionResult<TestCycleDto>>Create(SaveTestCycleRequest r,CancellationToken ct){try{return Ok(await service.CreateAsync(r,UserId(),ct));}catch(DuplicateCodeException ex){return Conflict(new ProblemDetails{Title="รหัส Test Cycle ซ้ำ",Detail=ex.Message,Status=409});}catch(Exception ex)when(ex is ArgumentException or EntityNotFoundException){return BadRequest(new ProblemDetails{Title="ข้อมูล Test Cycle ไม่ถูกต้อง",Detail=ex.Message,Status=400});}catch(Exception ex){return StatusCode(500,new ProblemDetails{Title="เกิดข้อผิดพลาด",Detail=ex.Message,Status=500});}}[HttpPut("test-cycles/{id:guid}")]public async Task<ActionResult<TestCycleDto>>Update(Guid id,SaveTestCycleRequest r,CancellationToken ct){try{return Ok(await service.UpdateAsync(id,r,ct));}catch(EntityNotFoundException){return NotFound();}catch(DuplicateCodeException ex){return Conflict(new ProblemDetails{Title="รหัส Test Cycle ซ้ำ",Detail=ex.Message,Status=409});}}[HttpPost("test-cycles/{id:guid}/status")]public async Task<ActionResult<TestCycleDto>>Status(Guid id,ChangeCycleStatusRequest r,CancellationToken ct){try{return Ok(await service.StatusAsync(id,r.Status,ct));}catch(EntityNotFoundException){return NotFound();}catch(ArgumentException ex){return BadRequest(new ProblemDetails{Title="สถานะไม่ถูกต้อง",Detail=ex.Message,Status=400});}}[HttpDelete("test-cycles/{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){try{await service.DeleteAsync(id,UserId(),ct);return NoContent();}catch(EntityNotFoundException){return NotFound();}}[HttpPost("test-cycles/generate-ai"),Authorize(Policy="ExecutionRun"),RequestSizeLimit(21_000_000)]public async Task<ActionResult<GeneratedTestCycle>>GenerateAi(GenerateTestCycleAiRequest request,CancellationToken ct){try{var project=(await projects.ListAsync(ct)).SingleOrDefault(x=>x.ProjectId==request.ProjectId)??throw new ArgumentException("ไม่พบ Project ที่เลือก");var release=await db.Releases.FirstOrDefaultAsync(x=>x.ReleaseId==request.ReleaseId&&x.ProjectId==request.ProjectId,ct)??throw new ArgumentException("ไม่พบ Release");var build=await db.Builds.FirstOrDefaultAsync(x=>x.BuildId==request.BuildId&&x.ReleaseId==request.ReleaseId,ct)??throw new ArgumentException("ไม่พบ Build");var environment=await db.TestEnvironments.FirstOrDefaultAsync(x=>x.TestEnvironmentId==request.EnvironmentId,ct)??throw new ArgumentException("ไม่พบ Environment");var testSuite=request.TestSuiteId.HasValue?await suites.GetAsync(request.TestSuiteId.Value,ct):null;return Ok(await ai.GenerateAsync(project,release,build,environment,testSuite,ct));}catch(ArgumentException ex){return BadRequest(new ProblemDetails{Title="ข้อมูลไม่ครบ",Detail=ex.Message,Status=400});}catch(InvalidOperationException ex){var status=ai.IsConfigured?502:503;return StatusCode(status,new ProblemDetails{Title="AI Generate Test Cycle ไม่พร้อมใช้งาน",Detail=ex.Message,Status=status});}catch(OperationCanceledException){return StatusCode(504,new ProblemDetails{Title="AI ใช้เวลาประมวลผลนานเกินไป",Detail="กรุณาลองใหม่อีกครั้ง",Status=504});}catch(Exception ex){return StatusCode(500,new ProblemDetails{Title="AI Generate Test Cycle ไม่สำเร็จ",Detail=ex.InnerException?.Message??ex.Message,Status=500});}}private Guid?UserId()=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var id)?id:null;
}
